_ns = {"__name__": "v102_embedded_v92"}
exec(compile(_b64.b64decode(_V92_B64), "<embedded-v92>", "exec"), _ns)

_SHOP_MAP = {
    "WHEAT": ("BAKERY",),
    "EGG": ("BRUNCH_SPOT", "BAKERY"),
    "MILK": ("ICE_CREAM_SHOP", "SMOOTHIE_SHOP", "PIZZA_SHOP"),
    "WOOL": ("YARN_STORE",),
    "CARROT": ("FARMERS_MARKET", "PET_CAFE"),
    "STRAWBERRY": ("ICE_CREAM_SHOP", "SMOOTHIE_SHOP", "FARMERS_MARKET", "BRUNCH_SPOT"),
    "MELON": ("SMOOTHIE_SHOP", "FARMERS_MARKET"),
    "TOMATO": ("PIZZA_SHOP", "FARMERS_MARKET"),
}
_CLEARANCE_STEP = 630

def agent(obs, configuration=None):
    action = _ns["_v92_entrypoint"](obs, configuration)
    if not isinstance(action, dict):
        return action
    day = int(obs.get("day", 0) or 0)
    hour = int(obs.get("hour", 0) or 0)
    step = obs.get("step")
    if step is None:
        step = day * 24 + hour
    shops = (obs.get("town") or {}).get("unlocked_shops") or []
    shops = set(shops)
    market = []
    for order in action.get("market", []):
        if not order:
            continue
        if order[0] == "SELL" and len(order) > 1:
            item = order[1]
            if item != "FERTILIZER" and int(step) < _CLEARANCE_STEP:
                required = _SHOP_MAP.get(item)
                if required and not any(shop in shops for shop in required):
                    continue
        market.append(order)
    action["market"] = market
    return action

def _kaggle_submission_entrypoint(obs, configuration=None):
    return agent(obs, configuration)
